#!/usr/bin/env bash
# Lets a platform admin add or remove a user's company membership directly
# from the admin panel (Platform > Users > a user's page), no email
# invite/acceptance round-trip needed — that flow (companies.py's
# invite_member) still exists and is unchanged; this is a second, more
# direct path for platform-admin use.
#
# Safety: same last-owner protection as the existing company-side member
# management — can't remove someone if they're a company's only owner.
# Duplicate memberships are rejected (existing role/company pair is left
# untouched, not silently overwritten). Both tested against a live server
# before this was shipped.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app/blueprints/platform.py app/templates/platform run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/platform"
cp app/blueprints/platform.py "backups/$TS/platform.py.bak" 2>/dev/null || true
cp app/templates/platform/user_detail.html "backups/$TS/templates/platform/user_detail.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/platform.py"
base64 -d > app/blueprints/platform.py << 'PLATFORM_PY_B64'

PLATFORM_PY_B64

echo "==> Writing app/templates/platform/user_detail.html"
base64 -d > app/templates/platform/user_detail.html << 'USER_DETAIL_HTML_B64'

USER_DETAIL_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/platform.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Done. Go to Platform > Users > pick a user, and their page now has:"
echo "  - An 'Add to company' form (company + role) on their membership"
echo "    panel — adds them immediately, no invite email needed."
echo "  - A 'Remove' button per existing membership."
echo "==================================================================="
